def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    k = 3  # Define the size of the sliding window
    rolling_max_list = []  # Initialize an empty list to store the rolling maximum elements

    for i in range(len(numbers) - k + 1):
        window = numbers[i:i+k]  # Get the current window of size k
        max_element = max(window)  # Find the maximum element in the window
        rolling_max_list.append(max_element)  # Append the maximum element to the rolling maximum list

    return rolling_max_list
